// Writes src/environments/primeui-license.ts from the PRIMEUI_LICENSE env var.
//
// Usage (runs automatically via the prestart / prebuild npm hooks):
//   node scripts/write-primeui-license.mjs
//
// PrimeNG 22 shows an "Invalid PrimeUI License" banner unless providePrimeNG() gets a valid key
// (https://primeng.dev/installation#license). The key ends up in the client bundle anyway —
// PrimeUI's Community terms allow that — but it must not be published in this public repo, so the
// generated file is gitignored and the key lives in .env.local locally / Vercel env vars in prod.
//
// A missing key is not a build error: the app still works, PrimeNG just shows its banner.

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(import.meta.dirname, '..');
const OUT_FILE = path.join(ROOT, 'src/environments/primeui-license.ts');
const ENV_FILE = path.join(ROOT, '.env.local');

// .env.local is a local convenience only; a real env var (e.g. on Vercel) wins.
function readEnvFile() {
  if (!existsSync(ENV_FILE)) return undefined;
  const line = readFileSync(ENV_FILE, 'utf8')
    .split(/\r?\n/)
    .find((l) => l.startsWith('PRIMEUI_LICENSE='));
  return line?.slice('PRIMEUI_LICENSE='.length).trim().replace(/^["']|["']$/g, '');
}

const key = (process.env.PRIMEUI_LICENSE ?? readEnvFile() ?? '').trim();

writeFileSync(
  OUT_FILE,
  '// Generated by scripts/write-primeui-license.mjs — do not edit or commit.\n' +
    `export const PRIMEUI_LICENSE = ${JSON.stringify(key)};\n`,
);

console.log(
  key
    ? `[primeui-license] wrote key (${key.length} chars) to ${path.relative(ROOT, OUT_FILE)}`
    : '[primeui-license] PRIMEUI_LICENSE not set — PrimeNG will show its license banner',
);
